function stringToBase64(str: string): string {
  const bytes =
    typeof TextEncoder !== 'undefined'
      ? new TextEncoder().encode(str)
      : Uint8Array.from(
          unescape(encodeURIComponent(str))
            .split('')
            .map((char) => char.charCodeAt(0)),
        );

  try {
    if (typeof btoa !== 'undefined') {
      let binary = '';
      const chunkSize = 32768;
      for (let index = 0; index < bytes.length; index += chunkSize) {
        const chunk = bytes.subarray(index, index + chunkSize);
        binary += String.fromCharCode(...chunk);
      }
      return btoa(binary);
    }
  } catch (error) {
    void error;
    // Fall back to manual encoding below.
  }

  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let result = '';
  let i = 0;

  while (i < bytes.length) {
    const a = bytes[i++];
    const hasB = i < bytes.length;
    const b = hasB ? bytes[i++] : 0;
    const hasC = i < bytes.length;
    const c = hasC ? bytes[i++] : 0;

    const bitmap = (a << 16) | (b << 8) | c;

    result += chars.charAt((bitmap >> 18) & 63);
    result += chars.charAt((bitmap >> 12) & 63);
    result += hasB ? chars.charAt((bitmap >> 6) & 63) : '=';
    result += hasC ? chars.charAt(bitmap & 63) : '=';
  }

  return result;
}

function buildGitHubAuthError(): string {
  return 'Ошибка аутентификации. GitHub token может быть неправильным, истёкшим или с недостаточными правами. Получите новый token на https://github.com/settings/tokens с scope "repo"';
}

function buildGitHubAccessError(): string {
  return 'Доступ запрещён. Проверьте, что у вас есть доступ к репозиторию ackedze/design-system_ab';
}

function base64ToString(value: string): string {
  const normalized = value.replace(/\s+/g, '');
  let bytes: Uint8Array;

  if (typeof atob !== 'undefined') {
    const binary = atob(normalized);
    bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
  } else {
    const chars =
      'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
    const decodedBytes: number[] = [];
    let i = 0;

    while (i < normalized.length) {
      const enc1 = chars.indexOf(normalized.charAt(i++));
      const enc2 = chars.indexOf(normalized.charAt(i++));
      const enc3 = chars.indexOf(normalized.charAt(i++));
      const enc4 = chars.indexOf(normalized.charAt(i++));

      const chr1 = (enc1 << 2) | (enc2 >> 4);
      const chr2 = ((enc2 & 15) << 4) | (enc3 >> 2);
      const chr3 = ((enc3 & 3) << 6) | enc4;

      decodedBytes.push(chr1);
      if (enc3 !== 64) {
        decodedBytes.push(chr2);
      }
      if (enc4 !== 64) {
        decodedBytes.push(chr3);
      }
    }

    bytes = Uint8Array.from(decodedBytes);
  }

  if (typeof TextDecoder !== 'undefined') {
    return new TextDecoder().decode(bytes);
  }

  let binary = '';
  const chunkSize = 32768;
  for (let index = 0; index < bytes.length; index += chunkSize) {
    const chunk = bytes.subarray(index, index + chunkSize);
    binary += String.fromCharCode(...chunk);
  }
  return decodeURIComponent(escape(binary));
}

function extractFigmaFileKey(link: string | undefined): string | undefined {
  if (!link) return undefined;
  const match = link.match(/figma\.com\/(?:design|file)\/([^/?#]+)/i);
  return match?.[1];
}

function resolveReferenceSourceFileKey(
  source: ReferenceCatalogSource | undefined,
): string | undefined {
  if (!source) return undefined;
  return (
    source.fileKey ||
    extractFigmaFileKey(source.figmaLibLink) ||
    extractFigmaFileKey(source.figmaPageLink) ||
    extractFigmaFileKey(source.figmaLink)
  );
}

function resolveCurrentFileKey(meta: PublishMeta | undefined): string | undefined {
  if (typeof meta?.fileKey === 'string' && meta.fileKey.trim()) {
    return meta.fileKey.trim();
  }

  const linkFileKey =
    typeof meta?.figmaLink === 'string'
      ? extractFigmaFileKey(meta.figmaLink)
      : undefined;
  if (linkFileKey) {
    return linkFileKey;
  }

  return figma.fileKey;
}

function normalizeMatchKey(value: string | undefined): string {
  return (value ?? '').trim().toLowerCase();
}

function normalizeLooseMatchKey(value: string | undefined): string {
  return (value ?? '')
    .replace(/\.json$/i, '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9а-яё]+/gi, '-')
    .replace(/^-+|-+$/g, '');
}

function normalizeRepoPath(value: string): string {
  return value.replace(/^\/+/, '').trim();
}

function readString(value: unknown): string | undefined {
  if (typeof value !== 'string') {
    return undefined;
  }

  const trimmed = value.trim();
  return trimmed || undefined;
}

function stripJsonExtension(value: string): string {
  return value.replace(/\.json$/i, '');
}

function sanitizeRepoFileName(value: string, fallback: string): string {
  const normalized = stripJsonExtension(getPathBaseName(value))
    .replace(/[\\/:*?"<>|]+/g, '_')
    .replace(/\s+/g, ' ')
    .trim();

  return normalized || fallback;
}

function getRepoDirectory(value: string | undefined): string {
  if (!value) {
    return '';
  }

  const normalized = normalizeRepoPath(value).replace(/\\/g, '/');
  const slashIndex = normalized.lastIndexOf('/');
  return slashIndex === -1 ? '' : normalized.slice(0, slashIndex);
}

function getManifestPublishRoot(): string {
  const normalizedPath = normalizeRepoPath(REFERENCE_SOURCES_PATH);
  const lastSlashIndex = normalizedPath.lastIndexOf('/');
  if (lastSlashIndex === -1) {
    return normalizedPath;
  }
  return normalizedPath.slice(0, lastSlashIndex);
}

function resolvePublishRootFromBaseUrl(baseUrl: string | undefined): string {
  const manifestRoot = getManifestPublishRoot();
  if (!baseUrl) return manifestRoot;

  try {
    const url = new URL(baseUrl);
    const segments = url.pathname
      .split('/')
      .map((segment) => segment.trim())
      .filter(Boolean);

    if (segments.length > 0 && normalizeMatchKey(segments[0]) === GITHUB_REPO) {
      segments.shift();
    }

    const parsedRoot = normalizeRepoPath(segments.join('/'));
    return parsedRoot || manifestRoot;
  } catch (error) {
    void error;
    return manifestRoot;
  }
}

function joinRepoPath(root: string, relativePath: string): string {
  const normalizedRoot = normalizeRepoPath(root);
  const normalizedPath = normalizeRepoPath(relativePath);

  if (!normalizedRoot) {
    return normalizedPath;
  }
  if (
    normalizeMatchKey(normalizedPath) === normalizeMatchKey(normalizedRoot) ||
    normalizeMatchKey(normalizedPath).startsWith(
      normalizeMatchKey(normalizedRoot) + '/',
    )
  ) {
    return normalizedPath;
  }

  return `${normalizedRoot}/${normalizedPath}`;
}

function getPathBaseName(value: string | undefined): string {
  if (!value) return '';
  const normalized = value.replace(/\\/g, '/');
  const parts = normalized.split('/');
  return parts[parts.length - 1] ?? normalized;
}

function matchesReferenceEntry(
  entry: ReferenceCatalogEntry,
  target: {
    kind?: PublishArtifactKind;
    fileKey?: string;
    catalogName?: string;
    pageName?: string;
  },
): boolean {
  const source = entry.source;
  if (!source || !target.kind) return false;
  if (source.kind !== target.kind) return false;

  const entryFileKey = resolveReferenceSourceFileKey(source);
  if (
    entryFileKey &&
    target.fileKey &&
    normalizeMatchKey(entryFileKey) !== normalizeMatchKey(target.fileKey)
  ) {
    return false;
  }

  const entryBaseName = getPathBaseName(entry.path || entry.fileName);
  const entryFileName = getPathBaseName(entry.fileName);
  const nameMatches =
    normalizeLooseMatchKey(entryBaseName) ===
      normalizeLooseMatchKey(target.catalogName) ||
    normalizeLooseMatchKey(entryFileName) ===
      normalizeLooseMatchKey(target.catalogName);

  if (target.kind === 'components') {
    const pageMatches =
      normalizeLooseMatchKey(source.pageName) ===
      normalizeLooseMatchKey(target.pageName);

    if (pageMatches || nameMatches) {
      return true;
    }
    return false;
  }

  if (nameMatches) {
    return true;
  }

  return Boolean(entryFileKey && target.fileKey);
}

function normalizeReferenceCatalogEntries(
  referenceList: ReferenceCatalogList | null,
): ReferenceCatalogEntry[] {
  if (!referenceList) {
    return [];
  }

  const flatCatalogs = Array.isArray(referenceList.catalogs)
    ? referenceList.catalogs
    : [];
  const libraryCatalogs: ReferenceCatalogEntry[] = [];

  if (Array.isArray(referenceList.libraries)) {
    referenceList.libraries.forEach((library) => {
      const catalogs = Array.isArray(library.catalogs) ? library.catalogs : [];
      catalogs.forEach((entry) => {
        libraryCatalogs.push(
          Object.assign({}, entry, {
            source: Object.assign({}, library.source || {}, entry.source || {}),
          }),
        );
      });
    });
  }

  return flatCatalogs.concat(libraryCatalogs);
}

function createEmptyReferenceCatalogList(): ReferenceCatalogList {
  return {
    baseUrl: `https://${GITHUB_OWNER}.github.io/${GITHUB_REPO}/JSONS/`,
    libraries: [],
  };
}

async function fetchReferenceCatalogFile(
  githubToken: string,
): Promise<ReferenceCatalogFile> {
  const apiUrl = `https://api.github.com/repos/${GITHUB_OWNER}/${GITHUB_REPO}/contents/${REFERENCE_SOURCES_PATH}`;
  const response = await fetch(apiUrl, {
    headers: {
      Authorization: `token ${githubToken}`,
      Accept: 'application/vnd.github.v3+json',
    },
  });

  if (response.status === 404) {
    return { list: null };
  }
  if (response.status === 401) {
    throw new Error(buildGitHubAuthError());
  }
  if (response.status === 403) {
    throw new Error(buildGitHubAccessError());
  }
  if (!response.ok) {
    throw new Error(
      `Не удалось загрузить referenceSourcesMVP.json: ${response.status} ${response.statusText}`,
    );
  }

  const payload = (await response.json()) as { content?: string; sha?: string };
  if (!payload.content) {
    return { list: null, sha: payload.sha };
  }

  return {
    list: JSON.parse(base64ToString(payload.content)) as ReferenceCatalogList,
    sha: payload.sha,
  };
}

async function putReferenceCatalogList(
  referenceList: ReferenceCatalogList,
  sha: string | undefined,
  githubToken: string,
  catalogName: string,
): Promise<void> {
  const apiUrl = `https://api.github.com/repos/${GITHUB_OWNER}/${GITHUB_REPO}/contents/${REFERENCE_SOURCES_PATH}`;
  const requestBody: any = {
    message: `Register design system catalog: ${stripJsonExtension(catalogName)}`,
    content: stringToBase64(`${JSON.stringify(referenceList, null, 2)}\n`),
  };

  if (sha) {
    requestBody.sha = sha;
  }

  const response = await fetch(apiUrl, {
    method: 'PUT',
    headers: {
      Authorization: `token ${githubToken}`,
      Accept: 'application/vnd.github.v3+json',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(requestBody),
  });

  if (!response.ok) {
    const errorData = await response.json();
    let errorMessage = errorData.message || response.statusText;

    if (response.status === 401) {
      errorMessage = buildGitHubAuthError();
    } else if (response.status === 403) {
      errorMessage = buildGitHubAccessError();
    } else if (response.status === 409) {
      errorMessage =
        'referenceSourcesMVP.json был изменён параллельно. Повторите публикацию, чтобы Athena подтянула свежую версию.';
    }

    throw new Error(`Не удалось обновить referenceSourcesMVP.json: ${errorMessage}`);
  }
}

function findReferenceLibrary(
  referenceList: ReferenceCatalogList,
  target: {
    catalogName: string;
    fileKey?: string;
    meta?: PublishMeta;
  },
): ReferenceLibrary {
  if (!Array.isArray(referenceList.libraries)) {
    referenceList.libraries = [];
  }

  const libraryName =
    readString(target.meta?.library) ||
    readString(target.meta?.fileName) ||
    sanitizeRepoFileName(target.catalogName, 'library');
  const normalizedLibraryName = normalizeLooseMatchKey(libraryName);

  const libraryByFileKey = referenceList.libraries.find((library) => {
    const libraryFileKey = resolveReferenceSourceFileKey(library.source);
    return (
      libraryFileKey &&
      target.fileKey &&
      normalizeMatchKey(libraryFileKey) === normalizeMatchKey(target.fileKey)
    );
  });
  if (libraryByFileKey) {
    return libraryByFileKey;
  }

  const libraryByName = referenceList.libraries
    .filter((library) => normalizeLooseMatchKey(library.name) === normalizedLibraryName)
    .sort((a, b) => scoreReferenceLibrary(b) - scoreReferenceLibrary(a))[0];
  if (libraryByName) {
    return libraryByName;
  }

  const source: ReferenceCatalogSource = {};
  const figmaLink = readString(target.meta?.figmaLink);
  if (figmaLink) {
    source.figmaLibLink = figmaLink;
  }
  if (target.fileKey) {
    source.fileKey = target.fileKey;
  }

  const library: ReferenceLibrary = {
    name: libraryName,
    source,
    catalogs: [],
  };
  referenceList.libraries.push(library);

  return library;
}

function scoreReferenceLibrary(library: ReferenceLibrary): number {
  const catalogCount = Array.isArray(library.catalogs) ? library.catalogs.length : 0;
  const hasSource = library.source && Object.keys(library.source).length > 0;
  return catalogCount + (hasSource ? 1000 : 0);
}

function inferCatalogDirectory(
  referenceList: ReferenceCatalogList,
  library: ReferenceLibrary,
  kind: PublishArtifactKind,
): string {
  if (kind === 'tokens') {
    return 'tokens';
  }
  if (kind === 'styles') {
    return 'styles';
  }

  const normalizedLibraryName = normalizeLooseMatchKey(library.name);
  const libraries = Array.isArray(referenceList.libraries)
    ? referenceList.libraries.filter(
        (candidate) =>
          normalizeLooseMatchKey(candidate.name) === normalizedLibraryName,
      )
    : [library];
  const catalogs = libraries.flatMap((candidate) =>
    Array.isArray(candidate.catalogs) ? candidate.catalogs : [],
  );
  const directoryCounts: Record<string, number> = {};

  catalogs.forEach((entry) => {
    const entryKind = entry.source?.kind;
    if (entryKind !== kind) {
      return;
    }

    const directory = getRepoDirectory(entry.path || entry.fileName);
    if (!directory) {
      return;
    }

    directoryCounts[directory] = (directoryCounts[directory] || 0) + 1;
  });

  let bestDirectory = '';
  let bestCount = 0;
  Object.keys(directoryCounts).forEach((directory) => {
    const count = directoryCounts[directory];
    if (count > bestCount) {
      bestDirectory = directory;
      bestCount = count;
    }
  });

  if (bestDirectory) {
    return bestDirectory;
  }

  return inferComponentLibraryDirectory(library.name);
}

function inferComponentLibraryDirectory(libraryName: string | undefined): string {
  const normalizedName = normalizeLooseMatchKey(libraryName);
  if (normalizedName.startsWith('web-')) {
    return `web/components/${normalizedName}`;
  }

  return `components/${sanitizeRepoFileName(libraryName || '', 'library')}`;
}

function buildReferenceCatalogEntry(
  payload: PublishPayload,
  target: {
    kind: PublishArtifactKind;
    fileKey?: string;
    pageName: string;
    relativePath: string;
  },
): ReferenceCatalogEntry {
  const source: ReferenceCatalogSource = {
    kind: target.kind,
    pageName: target.pageName,
  };

  const figmaLink = readString(payload.meta?.figmaLink);
  if (figmaLink) {
    source.figmaPageLink = figmaLink;
  }
  if (target.fileKey) {
    source.fileKey = target.fileKey;
  }

  return {
    fileName: target.relativePath,
    path: target.relativePath,
    source,
  };
}

function registerReferenceCatalogEntry(
  referenceList: ReferenceCatalogList,
  payload: PublishPayload,
  target: {
    kind: PublishArtifactKind;
    fileKey?: string;
    pageName: string;
  },
): ReferenceCatalogEntry {
  const library = findReferenceLibrary(referenceList, {
    catalogName: payload.catalogName,
    fileKey: target.fileKey,
    meta: payload.meta,
  });

  if (!Array.isArray(library.catalogs)) {
    library.catalogs = [];
  }

  const catalogBaseName = sanitizeRepoFileName(payload.catalogName, 'catalog');
  const directory = inferCatalogDirectory(referenceList, library, target.kind);
  const relativePath = joinRepoPath(directory, `${catalogBaseName}.json`);

  const duplicateEntry = library.catalogs.find(
    (entry) =>
      normalizeMatchKey(entry.path) === normalizeMatchKey(relativePath) ||
      matchesReferenceEntry(entry, {
        kind: target.kind,
        catalogName: payload.catalogName,
        fileKey: target.fileKey,
        pageName: target.pageName,
      }),
  );

  if (duplicateEntry) {
    return duplicateEntry;
  }

  const entry = buildReferenceCatalogEntry(payload, {
    kind: target.kind,
    fileKey: target.fileKey,
    pageName: target.pageName,
    relativePath,
  });
  library.catalogs.push(entry);
  return entry;
}

async function resolvePublishFilePath(
  payload: PublishPayload,
  githubToken: string,
): Promise<PublishFileResolution> {
  const kind = payload.meta?.kind;
  const fileKey = resolveCurrentFileKey(payload.meta);
  const pageName =
    typeof payload.meta?.pageName === 'string' ? payload.meta.pageName : '';

  if (!kind) {
    throw new Error(
      'Не удалось определить тип публикуемого каталога. Для публикации нужен kind.',
    );
  }
  if (kind === 'component-index') {
    throw new Error('component-index публикуется только как связанный артефакт каталога компонентов.');
  }

  const referenceFile = await fetchReferenceCatalogFile(githubToken);
  const referenceList = referenceFile.list || createEmptyReferenceCatalogList();
  const referenceEntries = normalizeReferenceCatalogEntries(referenceList);
  const matchedEntry = referenceEntries.find((entry) =>
    matchesReferenceEntry(entry, {
      kind,
      catalogName: payload.catalogName,
      fileKey,
      pageName,
    }),
  );

  let referenceUpdated = false;
  let resolvedEntry = matchedEntry;
  if (!resolvedEntry?.path) {
    resolvedEntry = registerReferenceCatalogEntry(referenceList, payload, {
      kind,
      fileKey,
      pageName: pageName || stripJsonExtension(payload.catalogName),
    });
    referenceUpdated = true;

    console.log('[CODE] reference catalog registered:', {
      catalogName: payload.catalogName,
      path: resolvedEntry.path,
      kind,
      fileKey,
      pageName,
    });
  }

  const publishRoot = resolvePublishRootFromBaseUrl(referenceList?.baseUrl);
  const referencePath = resolvedEntry.path;
  return {
    filePath: joinRepoPath(publishRoot, referencePath),
    referenceUpdated,
    referencePath,
    referenceList: referenceUpdated ? referenceList : undefined,
    referenceSha: referenceUpdated ? referenceFile.sha : undefined,
  };
}

function buildComponentIndexPath(catalogPath: string): string {
  const normalizedPath = normalizeRepoPath(catalogPath);
  const manifestRoot = getManifestPublishRoot();
  const rootPrefix = normalizedPath.startsWith(`${manifestRoot}/`)
    ? `${manifestRoot}/`
    : '';
  const relativeCatalogPath = rootPrefix
    ? normalizedPath.slice(rootPrefix.length)
    : normalizedPath;
  const indexRelativePath = relativeCatalogPath.replace(/\.json$/i, '.index.json');

  return joinRepoPath(rootPrefix ? `${manifestRoot}/indexes` : 'indexes', indexRelativePath);
}

function buildComponentPackageArtifactPath(
  catalogPath: string,
  packageName: string,
  fileName: string,
): string {
  const normalizedCatalogPath = normalizeRepoPath(catalogPath);
  const catalogDirectory = getRepoDirectory(normalizedCatalogPath);
  return joinRepoPath(catalogDirectory, `${packageName}/${fileName}`);
}

function enrichComponentIndexJson(
  rawJson: string,
  context: {
    catalogPath: string;
    indexPath: string;
  },
): string {
  const parsed = JSON.parse(rawJson);
  if (!parsed || typeof parsed !== 'object') {
    throw new Error('Invalid component index payload');
  }

  const payload = parsed as Record<string, unknown>;
  payload.catalogPath = context.catalogPath;
  payload.indexPath = context.indexPath;

  if (Array.isArray(payload.components)) {
    payload.components = payload.components.map((entry) => {
      if (!entry || typeof entry !== 'object') {
        return entry;
      }
      return Object.assign({}, entry, {
        catalogPath: context.catalogPath,
        indexPath: context.indexPath,
      });
    });
  }

  if (Array.isArray(payload.entries)) {
    payload.entries = payload.entries.map((entry) => {
      if (!entry || typeof entry !== 'object') {
        return entry;
      }
      return Object.assign({}, entry, {
        catalogPath: context.catalogPath,
        indexPath: context.indexPath,
      });
    });
  }

  return JSON.stringify(payload, null, 2);
}

async function mergeComponentPackageArtifactJson(
  apiUrl: string,
  githubToken: string,
  nextJson: string,
): Promise<string> {
  const existingJson = await fetchExistingGitHubJson(apiUrl, githubToken);
  if (!existingJson) {
    return nextJson;
  }

  const existing = parseJsonObject(existingJson);
  const next = parseJsonObject(nextJson);
  if (!existing || !next) {
    return nextJson;
  }

  const documentType = readString(next.documentType);
  if (documentType === 'component-agent-context') {
    return JSON.stringify(mergeAgentContextArtifact(existing, next), null, 2);
  }
  if (documentType === 'component-audit-mapping') {
    return JSON.stringify(mergeAuditMappingArtifact(existing, next), null, 2);
  }

  return nextJson;
}

function mergeAgentContextArtifact(
  existing: Record<string, unknown>,
  next: Record<string, unknown>,
): Record<string, unknown> {
  const generated = readRecord(next.generated) || {};
  const manual = readRecord(existing.manual) || extractAgentContextManual(existing);
  return stripUndefinedProperties({
    ...next,
    status: readString(existing.status) || readString(next.status) || 'draft',
    manual,
    summary: readString(manual.summary) || readString(next.summary),
    criticalBaselines: manual.criticalBaselines || next.criticalBaselines,
    agentInstructions: manual.agentInstructions || next.agentInstructions,
    codeExports: manual.codeExports || next.codeExports,
    auditInterpretation: manual.auditInterpretation || next.auditInterpretation,
    source: generated.source || next.source,
    sourceFiles: generated.sourceFiles || next.sourceFiles,
    components: generated.components || next.components,
    includedComponents: generated.components || next.includedComponents,
  });
}

function mergeAuditMappingArtifact(
  existing: Record<string, unknown>,
  next: Record<string, unknown>,
): Record<string, unknown> {
  const generated = readRecord(next.generated) || {};
  const manual = readRecord(existing.manual) || extractAuditMappingManual(existing);
  return stripUndefinedProperties({
    ...next,
    status: readString(existing.status) || readString(next.status) || 'draft',
    manual,
    classification: generated.classification || next.classification,
    groupingOrder: generated.groupingOrder || next.groupingOrder,
    evidencePolicy: generated.evidencePolicy || next.evidencePolicy,
    categories: manual.categories || generated.categories || next.categories,
    hostIntegrationNote: manual.hostIntegrationNote || next.hostIntegrationNote,
    codeExportAliases: manual.codeExportAliases || next.codeExportAliases,
  });
}

function extractAgentContextManual(
  existing: Record<string, unknown>,
): Record<string, unknown> {
  return stripUndefinedProperties({
    summary: existing.summary,
    criticalBaselines: existing.criticalBaselines,
    agentInstructions: existing.agentInstructions,
    codeExports: existing.codeExports,
    auditInterpretation: existing.auditInterpretation,
    notes: existing.notes,
  });
}

function extractAuditMappingManual(
  existing: Record<string, unknown>,
): Record<string, unknown> {
  return stripUndefinedProperties({
    categories: existing.categories,
    hostIntegrationNote: existing.hostIntegrationNote,
    codeExportAliases: existing.codeExportAliases,
    notes: existing.notes,
  });
}

function stripUndefinedProperties(
  input: Record<string, unknown>,
): Record<string, unknown> {
  const output: Record<string, unknown> = {};
  Object.keys(input).forEach((key) => {
    if (input[key] !== undefined) {
      output[key] = input[key];
    }
  });
  return output;
}

function parseJsonObject(value: string): Record<string, unknown> | undefined {
  try {
    const parsed = JSON.parse(value);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      return parsed as Record<string, unknown>;
    }
  } catch (error) {
    console.warn('[CODE] failed to parse GitHub json for merge', error);
  }
  return undefined;
}

function readRecord(value: unknown): Record<string, unknown> | undefined {
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    return value as Record<string, unknown>;
  }
  return undefined;
}

async function getExistingFileSha(
  apiUrl: string,
  githubToken: string,
): Promise<string | undefined> {
  const response = await fetch(apiUrl, {
    headers: {
      Authorization: `token ${githubToken}`,
      Accept: 'application/vnd.github.v3+json',
    },
  });

  if (response.status === 404) {
    return undefined;
  }
  if (response.status === 401) {
    throw new Error(buildGitHubAuthError());
  }
  if (response.status === 403) {
    throw new Error(buildGitHubAccessError());
  }
  if (!response.ok) {
    throw new Error(
      `Не удалось проверить существующий файл в GitHub: ${response.status} ${response.statusText}`,
    );
  }

  const fileData = (await response.json()) as { sha?: string };
  return fileData.sha;
}

async function fetchExistingGitHubJson(
  apiUrl: string,
  githubToken: string,
): Promise<string | undefined> {
  const response = await fetch(apiUrl, {
    headers: {
      Authorization: `token ${githubToken}`,
      Accept: 'application/vnd.github.v3+json',
    },
  });

  if (response.status === 404) {
    return undefined;
  }
  if (!response.ok) {
    throw new Error(
      `Не удалось прочитать существующий package artifact из GitHub: ${response.status} ${response.statusText}`,
    );
  }

  const fileData = (await response.json()) as {
    content?: string;
    encoding?: string;
  };
  if (!fileData.content || fileData.encoding !== 'base64') {
    return undefined;
  }
  return base64ToString(fileData.content);
}

function isWebCorpComponentCatalogPath(filePath: string): boolean {
  const normalizedPath = normalizeRepoPath(filePath).replace(/\\/g, '/');
  return (
    normalizedPath === WEB_CORP_COMPONENTS_PATH ||
    normalizedPath.startsWith(`${WEB_CORP_COMPONENTS_PATH}/`)
  );
}

function getComponentPackageNameFromCatalog(
  catalogJson: string,
  catalogName: string,
): string | undefined {
  const catalog = parseJsonObject(catalogJson);
  const source = catalog ? readRecord(catalog.source) : undefined;
  const sourceFiles = source && Array.isArray(source.files) ? source.files : [];
  const sourceName = sourceFiles.find(
    (value) => typeof value === 'string' && value.trim(),
  );
  const fallbackName = stripJsonExtension(catalogName).replace(
    /^Web _ Corp Components -- /,
    '',
  );
  const packageName = String(sourceName || fallbackName)
    .replace(/::/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return packageName || undefined;
}

function slugifyComponentName(value: string): string {
  return String(value || '')
    .replace(/\[[DMT]\]/gi, ' ')
    .replace(/^[DMT]\]\s*/i, ' ')
    .replace(/\[[^\]]+\]/g, ' ')
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/[^\wА-Яа-яЁё]+/g, '-')
    .replace(/_+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .toLowerCase();
}

function getDefaultComponentKey(packageName: string): string {
  return `web-corp.${slugifyComponentName(packageName)}`;
}

function removeLeadingComponentMarkers(value: string): string {
  return String(value || '')
    .replace(/^[^\wА-Яа-яЁё\[]+\s*/u, '')
    .trim();
}

function addAlias(aliases: Set<string>, value: unknown): void {
  if (typeof value !== 'string') return;
  const normalized = value.trim();
  if (normalized) {
    aliases.add(normalized);
  }
}

function getCatalogAliases(catalogJson: string, packageName: string): string[] {
  const aliases = new Set<string>();
  addAlias(aliases, packageName);

  const catalog = parseJsonObject(catalogJson);
  const components = catalog && Array.isArray(catalog.components)
    ? catalog.components
    : [];
  components.forEach((component) => {
    const record = readRecord(component);
    const name = record ? readString(record.name) : undefined;
    if (!name) return;
    addAlias(aliases, name);
    addAlias(aliases, removeLeadingComponentMarkers(name));
  });

  return Array.from(aliases).sort((left, right) => left.localeCompare(right));
}

function buildDefaultComponentRules(
  catalogJson: string,
  packageName: string,
): Record<string, unknown> {
  const componentKey = getDefaultComponentKey(packageName);
  const aliases = getCatalogAliases(catalogJson, packageName);

  return {
    schemaVersion: 1,
    documentType: 'component-rules',
    componentKey,
    status: 'generated-draft',
    rules: [
      {
        ruleId: `component:${componentKey}.component-properties-are-first-class`,
        severity: 'info',
        source: 'component-contract',
        appliesTo: 'variant.*',
        checkType: 'deterministic',
        matchKind: 'exact_component_rule',
        target: {
          component: packageName,
          layers: aliases,
        },
        ruleText:
          'Изменения variant/property в этом семействе компонентов являются component-property customizations. Показывай их отдельно от производных визуальных изменений layer.',
      },
      {
        ruleId: `component:${componentKey}.layer-properties-use-effective-baseline`,
        severity: 'warning',
        source: 'composition-contract',
        appliesTo: 'layout.*|styles.text|fill|stroke|radius|opacity',
        checkType: 'deterministic',
        matchKind: 'exact_component_rule',
        target: {
          component: packageName,
          layers: aliases,
        },
        ruleText:
          'Изменения layer/style внутри этого семейства компонентов нужно сравнивать с effective baseline текущего component variant и nested owner context.',
      },
      {
        ruleId: `component:${componentKey}.lifecycle-context-is-informational`,
        severity: 'info',
        source: 'component-contract',
        appliesTo: 'component.status',
        checkType: 'manual',
        ruleText:
          'Lifecycle status компонента является контекстом для агента. Не считай его дизайн-нарушением, если не найден отдельный pattern или exact design rule.',
      },
    ],
  };
}

async function putGitHubJsonFile(
  apiUrl: string,
  githubToken: string,
  json: string,
  message: string,
  sha?: string,
): Promise<PublishedFileResult> {
  const requestBody: Record<string, unknown> = {
    message,
    content: stringToBase64(`${json.trim()}\n`),
  };
  if (sha) {
    requestBody.sha = sha;
  }

  const response = await fetch(apiUrl, {
    method: 'PUT',
    headers: {
      Authorization: `token ${githubToken}`,
      Accept: 'application/vnd.github.v3+json',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(requestBody),
  });

  if (!response.ok) {
    const errorData = await response.json();
    const errorMessage = errorData.message || response.statusText;
    throw new Error(`GitHub API error (${response.status}): ${errorMessage}`);
  }

  const result = (await response.json()) as { html_url?: string };
  return {
    catalogName: message,
    url: result.html_url || '',
  };
}

function buildRulesRegistryEntry(
  rules: Record<string, unknown>,
  packageName: string,
  rulesFilePath: string,
  catalogJson: string,
  existingEntry?: Record<string, unknown>,
): Record<string, unknown> {
  const aliases = new Set<string>();
  const existingAliases = existingEntry && Array.isArray(existingEntry.aliases)
    ? existingEntry.aliases
    : [];
  existingAliases.forEach((alias) => addAlias(aliases, alias));
  getCatalogAliases(catalogJson, packageName).forEach((alias) =>
    addAlias(aliases, alias),
  );

  return {
    componentKey:
      readString(rules.componentKey) || getDefaultComponentKey(packageName),
    packageName,
    aliases: Array.from(aliases).sort((left, right) =>
      left.localeCompare(right),
    ),
    rulesFile: rulesFilePath,
    rules: Array.isArray(rules.rules) ? rules.rules : [],
  };
}

function buildUpdatedRulesRegistry(
  existingRegistry: Record<string, unknown> | undefined,
  entry: Record<string, unknown>,
): Record<string, unknown> {
  const existingEntries = existingRegistry && Array.isArray(existingRegistry.entries)
    ? existingRegistry.entries
    : [];
  const packageName = readString(entry.packageName) || '';
  const componentKey = readString(entry.componentKey) || '';
  const entries = existingEntries
    .map((value) => readRecord(value))
    .filter((value): value is Record<string, unknown> => Boolean(value))
    .filter((value) => {
      return (
        readString(value.packageName) !== packageName &&
        readString(value.componentKey) !== componentKey
      );
    });

  entries.push(entry);
  entries.sort((left, right) => {
    const leftName = readString(left.packageName) || '';
    const rightName = readString(right.packageName) || '';
    return leftName.localeCompare(rightName);
  });

  return {
    schemaVersion: 1,
    documentType: 'apollo-component-rules-registry',
    generatedAt: new Date().toISOString(),
    entries,
  };
}

async function syncApolloRulesRegistry(
  filePath: string,
  catalogName: string,
  catalogJson: string,
  githubToken: string,
): Promise<ApolloRulesRegistrySyncResult | undefined> {
  if (!isWebCorpComponentCatalogPath(filePath)) {
    return undefined;
  }

  const packageName = getComponentPackageNameFromCatalog(catalogJson, catalogName);
  if (!packageName) {
    throw new Error('Не удалось определить имя пакета для обновления rules registry');
  }

  const packageRulesPath = buildComponentPackageArtifactPath(
    filePath,
    packageName,
    'rules.json',
  );
  const rulesApiUrl = `https://api.github.com/repos/${GITHUB_OWNER}/${GITHUB_REPO}/contents/${packageRulesPath}`;
  let rulesJson = await fetchExistingGitHubJson(rulesApiUrl, githubToken);
  let createdRules: PublishedFileResult | undefined;

  if (!rulesJson) {
    const defaultRules = buildDefaultComponentRules(catalogJson, packageName);
    rulesJson = JSON.stringify(defaultRules, null, 2);
    const created = await putGitHubJsonFile(
      rulesApiUrl,
      githubToken,
      rulesJson,
      `Create component rules: ${packageName}`,
    );
    createdRules = {
      catalogName: `${packageName} rules.json`,
      url: created.url,
    };
  }

  const rules = parseJsonObject(rulesJson);
  if (!rules || readString(rules.documentType) !== 'component-rules') {
    throw new Error(`Некорректный rules.json для пакета ${packageName}`);
  }

  const registryPath = joinRepoPath(
    getRepoDirectory(filePath),
    APOLLO_RULES_REGISTRY_FILE,
  );
  const registryApiUrl = `https://api.github.com/repos/${GITHUB_OWNER}/${GITHUB_REPO}/contents/${registryPath}`;

  for (let attempt = 1; attempt <= 3; attempt += 1) {
    const registryResponse = await fetch(registryApiUrl, {
      headers: {
        Authorization: `token ${githubToken}`,
        Accept: 'application/vnd.github.v3+json',
      },
    });

    if (registryResponse.status === 401) {
      throw new Error(buildGitHubAuthError());
    }
    if (registryResponse.status === 403) {
      throw new Error(buildGitHubAccessError());
    }
    if (registryResponse.status !== 404 && !registryResponse.ok) {
      throw new Error(
        `Не удалось прочитать Apollo rules registry: ${registryResponse.status} ${registryResponse.statusText}`,
      );
    }

    let registry: Record<string, unknown> | undefined;
    let registrySha: string | undefined;
    if (registryResponse.ok) {
      const registryFile = (await registryResponse.json()) as {
        content?: string;
        encoding?: string;
        sha?: string;
      };
      registrySha = registryFile.sha;
      registry = registryFile.content && registryFile.encoding === 'base64'
        ? parseJsonObject(base64ToString(registryFile.content))
        : undefined;
    }

    const existingEntry = registry && Array.isArray(registry.entries)
      ? registry.entries
          .map((value) => readRecord(value))
          .find((value) => value && readString(value.packageName) === packageName)
      : undefined;
    const entry = buildRulesRegistryEntry(
      rules,
      packageName,
      packageRulesPath,
      catalogJson,
      existingEntry,
    );
    const nextRegistry = buildUpdatedRulesRegistry(registry, entry);

    try {
      const published = await putGitHubJsonFile(
        registryApiUrl,
        githubToken,
        JSON.stringify(nextRegistry, null, 2),
        `Sync Apollo rules registry: ${packageName}`,
        registrySha,
      );
      return {
        packageName,
        createdRules,
        registry: {
          catalogName: APOLLO_RULES_REGISTRY_FILE,
          url: published.url,
        },
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : '';
      if (attempt < 3 && message.indexOf('409') !== -1) {
        continue;
      }
      throw error;
    }
  }

  throw new Error('Не удалось обновить Apollo rules registry после повторных попыток');
}

async function publishWithToken(payload: PublishPayload, githubToken: string) {
  try {
    if (!payload || !payload.json || !payload.catalogName) {
      throw new Error('Invalid publish payload');
    }

    if (!githubToken) {
      throw new Error('GitHub token is required');
    }

    const catalogName = payload.catalogName.replace(/\.json$/, '');
    const repo = `${GITHUB_OWNER}/${GITHUB_REPO}`;
    const owner = GITHUB_OWNER;
    const repoName = GITHUB_REPO;
    const publishResolution = await resolvePublishFilePath(payload, githubToken);
    const filePath = publishResolution.filePath;
    const publishTargets: PublishTarget[] = [
      {
        json: payload.json,
        catalogName,
        filePath,
        kind: payload.meta?.kind,
      },
    ];

    if (payload.meta?.kind === 'components' && payload.relatedArtifacts?.length) {
      for (const artifact of payload.relatedArtifacts) {
        if (artifact.meta?.kind === 'component-index') {
          const indexFilePath = buildComponentIndexPath(filePath);
          publishTargets.push({
            json: enrichComponentIndexJson(artifact.json, {
              catalogPath: filePath,
              indexPath: indexFilePath,
            }),
            catalogName: artifact.catalogName.replace(/\.json$/, ''),
            filePath: indexFilePath,
            kind: artifact.meta.kind,
          });
          continue;
        }

        if (artifact.meta?.kind === 'component-package') {
          const packageName = readString(artifact.meta.packageName);
          const artifactFileName = readString(artifact.meta.fileName);
          if (!packageName || !artifactFileName) {
            console.warn('[CODE] skip component-package artifact without packageName/fileName');
            continue;
          }
          const packageFilePath = buildComponentPackageArtifactPath(
            filePath,
            packageName,
            artifactFileName,
          );
          publishTargets.push({
            json: artifact.json,
            catalogName: artifact.catalogName.replace(/\.json$/, ''),
            filePath: packageFilePath,
            kind: artifact.meta.kind,
          });
        }
      }
    }

    console.log('[CODE] publishing to GitHub:', {
      catalogName,
      filePath,
      kind: payload.meta?.kind,
      fileKey: resolveCurrentFileKey(payload.meta),
      pageName: payload.meta?.pageName,
      relatedArtifacts: publishTargets.length - 1,
      referenceUpdated: publishResolution.referenceUpdated,
      referencePath: publishResolution.referencePath,
    });

    const results: Array<{ catalogName: string; url: string }> = [];
    for (const target of publishTargets) {
      const apiUrl = `https://api.github.com/repos/${owner}/${repoName}/contents/${target.filePath}`;
      const sha = await getExistingFileSha(apiUrl, githubToken);
      const targetJson =
        target.kind === 'component-package' && sha
          ? await mergeComponentPackageArtifactJson(apiUrl, githubToken, target.json)
          : target.json;
      const encodedContent = stringToBase64(targetJson);
      if (sha) {
        console.log('[CODE] existing file found, sha:', sha);
      } else {
        console.log('[CODE] file does not exist yet, creating new');
      }

      const requestBody: any = {
        message: `Publish design system catalog: ${target.catalogName}`,
        content: encodedContent,
      };
      if (sha) {
        requestBody.sha = sha;
      }

      const putResponse = await fetch(apiUrl, {
        method: 'PUT',
        headers: {
          Authorization: `token ${githubToken}`,
          Accept: 'application/vnd.github.v3+json',
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestBody),
      });

      if (!putResponse.ok) {
        const errorData = await putResponse.json();
        let errorMessage = errorData.message || putResponse.statusText;

        if (putResponse.status === 401) {
          errorMessage = buildGitHubAuthError();
        } else if (putResponse.status === 403) {
          errorMessage = buildGitHubAccessError();
        }

        throw new Error(`GitHub API error: ${errorMessage}`);
      }

      const result = await putResponse.json();
      console.log('[CODE] catalog published successfully:', {
        catalogName: target.catalogName,
        kind: target.kind,
        url: result.html_url,
      });
      results.push({ catalogName: target.catalogName, url: result.html_url });
    }

    if (payload.meta?.kind === 'components') {
      const rulesRegistrySync = await syncApolloRulesRegistry(
        filePath,
        catalogName,
        payload.json,
        githubToken,
      );
      if (rulesRegistrySync?.createdRules) {
        results.push(rulesRegistrySync.createdRules);
      }
      if (rulesRegistrySync?.registry) {
        results.push(rulesRegistrySync.registry);
        console.log('[CODE] Apollo rules registry synced:', {
          packageName: rulesRegistrySync.packageName,
          createdRules: Boolean(rulesRegistrySync.createdRules),
        });
      }
    }

    if (publishResolution.referenceUpdated && publishResolution.referenceList) {
      await putReferenceCatalogList(
        publishResolution.referenceList,
        publishResolution.referenceSha,
        githubToken,
        catalogName,
      );
      console.log('[CODE] referenceSourcesMVP.json updated:', {
        catalogName,
        referencePath: publishResolution.referencePath,
      });
    }

    const primaryResult = results[0];
    logDebug('publish-catalog-success', {
      catalogName,
      url: primaryResult?.url,
      files: results.length,
      referenceUpdated: publishResolution.referenceUpdated,
    });

    figma.notify(`✓ Опубликовано файлов: ${results.length} в ${repo}`, {
      timeout: 5000,
    });

    figma.ui.postMessage({
      type: 'publish-result',
      payload: {
        success: true,
        catalogName,
        url: primaryResult?.url,
        files: results,
        referenceUpdated: publishResolution.referenceUpdated,
        referencePath: publishResolution.referencePath,
      },
    });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : 'Неизвестная ошибка';
    console.error('[CODE] failed to publish catalog', error);
    logDebug('publish-catalog-error', { error: message });
    figma.notify(`Не удалось опубликовать каталог: ${message}`, {
      timeout: 5000,
    });
    figma.ui.postMessage({
      type: 'publish-result',
      payload: {
        success: false,
        error: message,
      },
    });
  }
}
